def gen(rng):
    def ser(vals, L, R):
        out = [str(vals[0])]
        q = [0]
        qi = 0
        while qi < len(q):
            u = q[qi]
            qi += 1
            for c in (L[u], R[u]):
                if c == -1:
                    out.append('null')
                else:
                    out.append(str(vals[c]))
                    q.append(c)
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def rand_tree(n, vmax):
        vals = [rng.randint(1, vmax)]
        L = [-1]
        R = [-1]
        free = [(0, 0), (0, 1)]
        for _ in range(n - 1):
            k = rng.randrange(len(free))
            free[k], free[-1] = free[-1], free[k]
            u, side = free.pop()
            v = len(vals)
            vals.append(rng.randint(1, vmax))
            L.append(-1)
            R.append(-1)
            if side == 0:
                L[u] = v
            else:
                R[u] = v
            free.append((v, 0))
            free.append((v, 1))
        return ser(vals, L, R)

    def chain(n, kind, vmax):
        vals = [rng.randint(1, vmax) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        for i in range(1, n):
            side = {'left': 0, 'right': 1, 'zig': i % 2}[kind]
            if side == 0:
                L[i - 1] = i
            else:
                R[i - 1] = i
        return ser(vals, L, R)

    def complete(n, vmax):
        vals = [rng.randint(1, vmax) for _ in range(n)]
        L = [2 * i + 1 if 2 * i + 1 < n else -1 for i in range(n)]
        R = [2 * i + 2 if 2 * i + 2 < n else -1 for i in range(n)]
        return ser(vals, L, R)

    def spine_with_bushes(n, vmax):
        # long left spine, with a right child hanging off every 3rd spine node
        vals = [rng.randint(1, vmax) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        spine = [0]
        nxt = 1
        while nxt < n:
            u = spine[-1]
            if len(spine) % 3 == 0 and nxt + 1 < n:
                R[u] = nxt
                nxt += 1
            L[u] = nxt
            spine.append(nxt)
            nxt += 1
        return ser(vals, L, R)

